package com.foldstandby.clock;

import android.app.Instrumentation;
import android.content.*;
import android.graphics.*;
import android.media.*;
import android.media.session.*;
import android.os.*;
import android.view.*;
import java.io.*;
import java.util.*;
import java.util.function.BiConsumer;

/** Real rendering, animation lifecycle and a local media session; never plays user audio. */
final class EffectsChecks {
    private static final int W=1080,H=684;
    private static Bitmap render(ClockFace face){face.measure(View.MeasureSpec.makeMeasureSpec(W,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(H,View.MeasureSpec.EXACTLY));face.layout(0,0,W,H);Bitmap bitmap=Bitmap.createBitmap(W,H,Bitmap.Config.ARGB_8888);face.draw(new Canvas(bitmap));return bitmap;}
    private static void save(Bitmap bitmap,File directory,String name)throws IOException{try(FileOutputStream stream=new FileOutputStream(new File(directory,name))){bitmap.compress(Bitmap.CompressFormat.PNG,100,stream);}}
    static int renderChecks(Context context,File directory,BiConsumer<Boolean,String> check)throws Exception{
        int count=0;android.content.SharedPreferences settings=context.getSharedPreferences("ui_checks",0);Scene scene=Scene.load(settings);Scene.Page page=scene.pages.get(0);Scene.put(scene.theme,"background",Color.WHITE);Scene.put(page.theme,"background",Color.YELLOW);
        check.accept(scene.color(page,page.slots[0],"background",false,false)==Color.BLACK,"black scene/page background despite legacy colors");
        for(String type:Scene.TYPES)for(int layout=0;layout<4;layout++)for(int night=0;night<2;night++){page.layout=layout;for(Scene.Component c:page.slots){c.type=type;Scene.put(c.theme,"background",Color.MAGENTA);}ClockFace face=new ClockFace(context,settings);face.bind(scene,0);face.demo=true;face.nightPreview=night==1;face.testTime=1234500;Bitmap bitmap=render(face);count++;check.accept(bitmap.getPixel(1,1)==Color.BLACK,"black page edge "+type);float gap=Math.min(W,H)*.025f,pad=gap*1.4f,cw=layout==3?(W-2*pad-gap)/2:layout==0?W-2*pad:(W-2*pad-gap)*(layout==2?.62f:.5f),ch=layout==3?(H-2*pad-gap)/2:H-2*pad,scale=Math.min(cw/540f,ch/432f);int x=Math.round(pad+cw/2+(15-250)*scale),y=Math.round(pad+ch/2+(15-200)*scale);check.accept(bitmap.getPixel(x,y)==Color.BLACK,"black component interior "+type+" / "+layout+" / "+night);if(night==0&&(type.equals("battery")||type.equals("music")))save(bitmap,directory,"new-"+type+"-"+layout+".png");bitmap.recycle();}
        page.layout=0;Scene.Component component=page.slots[0];component.type="clock";float scale=Math.min((W-2*H*.035f)/540f,(H-2*H*.035f)/432f);for(String style:Scene.STYLES){component.style=style;ClockFace face=new ClockFace(context,settings);face.bind(scene,0);face.nightPreview=false;Bitmap bitmap=render(face);count++;float logicalX=style.equals("industrial")?80:30,logicalY=style.equals("industrial")?50:110;int x=Math.round(W/2f+(logicalX-250)*scale),y=Math.round(H/2f+(logicalY-200)*scale);if(style.equals("flip")||style.equals("industrial"))check.accept(bitmap.getPixel(x,y)==Color.BLACK,"pure black clock plate "+style);bitmap.recycle();}
        for(int preset=0;preset<ColorThemes.NAMES.length;preset++)check.accept(ColorThemes.theme(preset).optInt("background")==Color.BLACK,"preset black background");
        check.accept(PageMotion.destination(2.4f,0,1,3)==3,"forward wrap slides into first page");check.accept(PageMotion.destination(.2f,2,-1,3)==-1,"reverse wrap retains direction");check.accept(PageMotion.destination(.4f,2,1,3)==2,"second swipe retains current position");check.accept(PageMotion.index(-1,3)==2,"negative page coordinate wraps");
        int level=DeskData.batteryLevel,temp=DeskData.batteryTempTenths;boolean charging=DeskData.batteryCharging,plugged=DeskData.batteryPlugged,full=DeskData.batteryFull;
        try{component.type="battery";ClockFace battery=new ClockFace(context,settings);battery.bind(scene,0);battery.nightPreview=false;battery.testTime=240;Intent value=new Intent().putExtra(BatteryManager.EXTRA_LEVEL,76).putExtra(BatteryManager.EXTRA_SCALE,100).putExtra(BatteryManager.EXTRA_PLUGGED,1).putExtra(BatteryManager.EXTRA_STATUS,BatteryManager.BATTERY_STATUS_CHARGING);DeskData.updateBattery(value);check.accept(DeskData.batteryCharging,"battery charging status");Bitmap first=render(battery);count++;save(first,directory,"charging-start.png");battery.testTime=1140;Bitmap second=render(battery);count++;save(second,directory,"charging-next.png");check.accept(!first.sameAs(second),"charging effect changes between frames");first.recycle();second.recycle();battery.nightPreview=true;check.accept(!battery.chargingAnimationForCheck(),"night stops charging animation");battery.nightPreview=false;battery.setMotionActive(false);check.accept(!battery.chargingAnimationForCheck(),"inactive view stops charging animation");battery.setMotionActive(true);DeskData.updateBattery(value.putExtra(BatteryManager.EXTRA_STATUS,BatteryManager.BATTERY_STATUS_NOT_CHARGING));check.accept(!DeskData.batteryCharging&&DeskData.batteryPlugged,"connected but not charging has no animation");DeskData.updateBattery(value.putExtra(BatteryManager.EXTRA_STATUS,BatteryManager.BATTERY_STATUS_FULL).putExtra(BatteryManager.EXTRA_LEVEL,100));check.accept(!battery.chargingAnimationForCheck()&&DeskData.batteryFull,"full battery stops animation");Bitmap image=render(battery);count++;save(image,directory,"battery-full.png");image.recycle();DeskData.updateBattery(value.putExtra(BatteryManager.EXTRA_PLUGGED,0).putExtra(BatteryManager.EXTRA_LEVEL,18).putExtra(BatteryManager.EXTRA_STATUS,BatteryManager.BATTERY_STATUS_DISCHARGING));image=render(battery);count++;save(image,directory,"battery-low.png");image.recycle();}
        finally{DeskData.batteryLevel=level;DeskData.batteryTempTenths=temp;DeskData.batteryCharging=charging;DeskData.batteryPlugged=plugged;DeskData.batteryFull=full;}
        check.accept(MediaControls.hit(250,310)==1&&MediaControls.hit(135,310)==0&&MediaControls.hit(365,310)==2,"music buttons have distinct hit regions");check.accept(MediaControls.hit(150,202)==-1,"music progress bar is not a transport button");check.accept(!MediaControls.enabled(PlaybackState.ACTION_PLAY,false,0),"undeclared previous action disabled");check.accept(MediaControls.enabled(PlaybackState.ACTION_PLAY,false,1),"play action enabled");check.accept(!MediaControls.enabled(PlaybackState.ACTION_PLAY,true,1),"play-only session cannot pause");check.accept(MediaControls.time(3661000).equals("1:01:01"),"long audio duration formatting");
        component.type="clock";component.style="digital";scene.pages.get(1).slots[0].type="battery";ClockFace moving=new ClockFace(context,settings);moving.bind(scene,0);moving.nightPreview=false;moving.demo=true;for(int style=0;style<2;style++)for(int frame=0;frame<5;frame++){moving.positionForCheck(frame/4f,style);Bitmap image=render(moving);count++;save(image,directory,"transition-"+style+"-"+frame+".png");check.accept(image.getPixel(1,1)==Color.BLACK,"transition has black viewport");image.recycle();}
        page.layout=1;page.slots[0].type="battery";page.slots[1].type="music";ClockFace widgets=new ClockFace(context,settings);widgets.bind(scene,0);widgets.nightPreview=false;widgets.demo=true;widgets.testTime=1234500;Bitmap paired=render(widgets);count++;save(paired,directory,"new-widgets.png");paired.recycle();
        page.slots[1].type="focus";ClockFace mixed=new ClockFace(context,settings);mixed.bind(scene,0);mixed.nightPreview=false;mixed.demo=true;mixed.testTime=1234500;Bitmap mixedImage=render(mixed);Scene reference=scene.copy();reference.pages.get(0).slots[0].type="clock";ClockFace referenceFace=new ClockFace(context,settings);referenceFace.bind(reference,0);referenceFace.nightPreview=false;referenceFace.demo=true;referenceFace.testTime=1234500;Bitmap referenceImage=render(referenceFace);count+=2;boolean same=true;for(int y=0;y<H;y++)for(int x=W/2+20;x<W;x++)same&=mixedImage.getPixel(x,y)==referenceImage.getPixel(x,y);check.accept(same,"battery drawing does not alter neighboring focus geometry");save(mixedImage,directory,"battery-focus.png");mixedImage.recycle();referenceImage.recycle();
        return count;
    }

    private final Instrumentation host;private int assertions;private Throwable error;
    private EffectsChecks(Instrumentation host){this.host=host;}
    private void check(boolean value,String message){assertions++;if(!value)throw new AssertionError(message);}
    private void sync(Runnable action){final Throwable[] failure={null};host.runOnMainSync(()->{try{action.run();}catch(Throwable e){failure[0]=e;}});if(failure[0]!=null)throw new AssertionError(failure[0]);}
    static Bundle run(Instrumentation host){return new EffectsChecks(host).run();}
    private Bundle run(){Bundle result=new Bundle();ClockActivity activity=null;SharedPreferences settings=host.getTargetContext().getSharedPreferences("ui_checks",0);Map<String,?> original=settings.getAll();try{
        mediaChecks();settings.edit().clear().putBoolean("night",false).putBoolean("motion",true).putInt("pageMotionDuration",520).commit();Scene model=Scene.load(settings);model.pages.get(0).layout=0;model.pages.get(0).slots[0].type="clock";model.pages.get(1).slots[0].type="battery";Scene.put(model.pages.get(1).theme,"accent",Color.RED);model.pages.get(2).slots[0].type="music";model.home=model.pages.get(0).id;model.save(settings);
        activity=(ClockActivity)host.startActivitySync(new Intent(host.getTargetContext(),ClockActivity.class).putExtra("uiCheck",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final ClockActivity screen=activity;host.waitForIdleSync();SystemClock.sleep(700);
        final ClockFace clock=find(screen.getWindow().getDecorView());check(clock!=null&&clock.getWidth()>0,"fullscreen clock is laid out");
        sync(()->{clock.demo=true;clock.nightPreview=false;check(android.animation.ValueAnimator.areAnimatorsEnabled(),"system animation is enabled for runtime check");swipe(clock,1);check(clock.pageAnimatingForCheck(),"manual swipe starts transition");});SystemClock.sleep(110);
        sync(()->{float position=clock.pagePositionForCheck();check(position>0&&position<1,"intermediate frame displays both pages");swipe(clock,1);check(Math.abs(clock.pagePositionForCheck()-position)<.03f,"rapid second swipe continues from visible position");});SystemClock.sleep(650);
        sync(()->{check(!clock.pageAnimatingForCheck()&&clock.pagePositionForCheck()==2,"rapid swipe ends on requested page");swipe(clock,-1);});SystemClock.sleep(650);sync(()->check(clock.chargingAnimationForCheck(),"visible charging example animates"));snapshot("runtime-battery.png");
        settings.edit().putInt("pageMotion",1).commit();sync(()->swipe(clock,1));SystemClock.sleep(120);snapshot("runtime-page-fade.png");SystemClock.sleep(550);sync(()->check(clock.pagePositionForCheck()==2&&!clock.pageAnimatingForCheck(),"fade finishes on target page"));snapshot("runtime-music.png");
        settings.edit().putInt("pageMotion",2).commit();sync(()->{swipe(clock,-1);check(!clock.pageAnimatingForCheck()&&clock.pagePositionForCheck()==1,"disabled page animation switches immediately");clock.nightPreview=true;check(!clock.chargingAnimationForCheck(),"night has no charging animation");clock.nightPreview=false;clock.setMotionActive(false);check(!clock.chargingAnimationForCheck(),"rest stops animation");clock.setMotionActive(true);});settings.edit().putInt("pageMotion",0).putBoolean("motion",false).commit();sync(()->{swipe(clock,-1);check(!clock.pageAnimatingForCheck(),"component motion setting also disables transition");});
        settings.edit().putBoolean("motion",true).commit();sync(()->{clock.selectPage(2);clock.animatePage(0,1,0,240);check(clock.pageAnimatingForCheck(),"autoplay wrap animates forward");});SystemClock.sleep(400);sync(()->{check(clock.pagePositionForCheck()==0,"wrapped transition finishes on home");});sync(()->{clock.selectPage(2);clock.animatePage(0,0,1,520);});SystemClock.sleep(130);sync(()->{Bitmap image=Bitmap.createBitmap(clock.getWidth(),clock.getHeight(),Bitmap.Config.ARGB_8888);clock.draw(new Canvas(image));boolean red=false;for(int y=0;y<image.getHeight();y+=3)for(int x=0;x<image.getWidth();x+=3){int pixel=image.getPixel(x,y);red|=Color.red(pixel)>80&&Color.red(pixel)>Color.green(pixel)*1.8f&&Color.red(pixel)>Color.blue(pixel)*1.8f;}image.recycle();check(!red,"nonadjacent home fade never flashes intermediate battery page");});SystemClock.sleep(550);sync(()->{clock.animatePage(1,1,0,520);clock.setMotionActive(false);check(!clock.pageAnimatingForCheck(),"rest cancels an in-flight transition");});
        result.putString("result","PASS: "+assertions+" animation and media-session checks");
    }catch(Throwable failure){error=failure;result.putString("result",android.util.Log.getStackTraceString(failure));}finally{if(activity!=null){final ClockActivity screen=activity;sync(screen::finish);}restore(settings,original);}result.putBoolean("passed",error==null);return result;}
    private static ClockFace find(View view){if(view instanceof ClockFace)return (ClockFace)view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++){ClockFace found=find(group.getChildAt(i));if(found!=null)return found;}}return null;}
    private void mediaChecks()throws Exception{final MediaSession[] session={null};final ClockFace[] face={null};final int[] commands={0,0,0,0};MediaController previous=DeskData.media;boolean allowed=DeskData.musicAllowed;long systemAt=DeskData.systemStateAt;try{
        sync(()->{session[0]=new MediaSession(host.getTargetContext(),"Fold UI validation");session[0].setCallback(new MediaSession.Callback(){public void onSkipToPrevious(){commands[0]++;}public void onPause(){commands[1]++;}public void onSkipToNext(){commands[2]++;}public void onPlay(){commands[3]++;}},new Handler(Looper.getMainLooper()));session[0].setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,"音乐控制验证").putString(MediaMetadata.METADATA_KEY_ARTIST,"本地测试会话").putLong(MediaMetadata.METADATA_KEY_DURATION,213000).build());session[0].setPlaybackState(new PlaybackState.Builder().setState(PlaybackState.STATE_PLAYING,74000,1).setActions(PlaybackState.ACTION_SKIP_TO_PREVIOUS|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_PAUSE).build());DeskData.media=new MediaController(host.getTargetContext(),session[0].getSessionToken());DeskData.musicAllowed=true;DeskData.systemStateAt=System.currentTimeMillis();Scene scene=Scene.load(host.getTargetContext().getSharedPreferences("ui_checks",0));scene.pages.get(0).layout=0;scene.pages.get(0).slots[0].type="music";face[0]=new ClockFace(host.getTargetContext());face[0].bind(scene,0);face[0].nightPreview=false;Bitmap image=render(face[0]);image.recycle();tap(face[0],150,202);});SystemClock.sleep(100);check(Arrays.equals(commands,new int[4]),"progress bar tap sends no media command");
        for(int button=0;button<3;button++){final int action=button;sync(()->tap(face[0],MediaControls.X[action],MediaControls.Y));SystemClock.sleep(120);check(commands[button]==1,"transport button reaches media session "+button);}
        sync(()->{session[0].setPlaybackState(new PlaybackState.Builder().setState(PlaybackState.STATE_PAUSED,74000,0).setActions(PlaybackState.ACTION_PLAY).build());});SystemClock.sleep(100);sync(()->tap(face[0],250,310));SystemClock.sleep(120);check(commands[3]==1,"paused session receives play");sync(()->tap(face[0],135,310));SystemClock.sleep(100);check(commands[0]==1,"unsupported skip sends no command");
    }finally{sync(()->{if(session[0]!=null)session[0].release();DeskData.media=previous;DeskData.musicAllowed=allowed;DeskData.systemStateAt=systemAt;});}}
    private void tap(ClockFace face,float x,float y){float scale=Math.min((W-2*H*.035f)/540f,(H-2*H*.035f)/432f);float actualX=W/2f+(x-250)*scale,actualY=H/2f+(y-200)*scale;long now=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,0,actualX,actualY,0),up=MotionEvent.obtain(now,now+80,1,actualX,actualY,0);face.onTouchEvent(down);face.onTouchEvent(up);down.recycle();up.recycle();}
    private void swipe(ClockFace face,int direction){long now=SystemClock.uptimeMillis();float start=direction>0?.75f:.25f,end=1-start;MotionEvent down=MotionEvent.obtain(now,now,0,face.getWidth()/2f,face.getHeight()*start,0),up=MotionEvent.obtain(now,now+180,1,face.getWidth()/2f,face.getHeight()*end,0);face.onTouchEvent(down);face.onTouchEvent(up);down.recycle();up.recycle();}
    private void snapshot(String name)throws IOException{Bitmap image=host.getUiAutomation().takeScreenshot();if(image!=null){File directory=new File(host.getTargetContext().getFilesDir(),"qa-0.3.2");directory.mkdirs();save(image,directory,name);image.recycle();}}
    private void restore(SharedPreferences prefs,Map<String,?> values){SharedPreferences.Editor editor=prefs.edit().clear();for(Map.Entry<String,?> entry:values.entrySet()){Object value=entry.getValue();String key=entry.getKey();if(value instanceof String)editor.putString(key,(String)value);else if(value instanceof Integer)editor.putInt(key,(Integer)value);else if(value instanceof Long)editor.putLong(key,(Long)value);else if(value instanceof Boolean)editor.putBoolean(key,(Boolean)value);else if(value instanceof Float)editor.putFloat(key,(Float)value);else if(value instanceof Set)editor.putStringSet(key,new HashSet<>((Set<String>)value));}editor.commit();}
}
